// ภาพหลักฐาน SVG ของเกม "อีนังงูพิษ" (viewBox 100×100) — วาดเองทั้งหมด สไตล์ flat มีเส้นขอบหมึก ไม่มีตัวหนังสือในภาพ
// หมวด: สัตว์ อาหาร ของใช้ อาวุธ ธรรมชาติ ยานพาหนะ/สถานที่ ร่างกาย/สัญลักษณ์ อารมณ์ สี
import React from 'react';

const INK = '#2b1d16';
const O = { stroke: INK, strokeWidth: 2.4, strokeLinejoin: 'round', strokeLinecap: 'round' };
const L = { stroke: INK, strokeWidth: 2.4, strokeLinecap: 'round', strokeLinejoin: 'round', fill: 'none' };
const f = fill => ({ fill, ...O });
const P = (n, fn) => Array.from({ length: n }, (_, i) => fn(i));
const star = (cx, cy, R, r, n = 5) => P(n * 2, i => { const a = -Math.PI / 2 + i * Math.PI / n, d = i % 2 ? r : R; return (i ? 'L' : 'M') + (cx + Math.cos(a) * d).toFixed(1) + ' ' + (cy + Math.sin(a) * d).toFixed(1); }).join('') + 'Z';
const Eye = ({ x, y, r = 3.2 }) => <g><circle cx={x} cy={y} r={r} fill={INK} /><circle cx={x + r * .35} cy={y - r * .35} r={r * .35} fill="#fff" /></g>;
const Shine = ({ d }) => <path d={d} fill="none" stroke="#fff" strokeOpacity=".75" strokeWidth="3" strokeLinecap="round" />;
const Blush = ({ x, y }) => <ellipse cx={x} cy={y} rx="4" ry="2.4" fill="#ff7b8a" opacity=".55" />;

const BG = { animal: '#d6efc4', food: '#ffe0b3', thing: '#dbe4f6', weapon: '#e9d4d0', nature: '#cde6ff', place: '#e6dbf6', body: '#ffd5d8', mood: '#fff0a6', color: '#f3eee4' };

