// ---------- 🎨 สี (โยงกับสีตัวละครของผู้เล่น) ----------
const splat = c => <g><path d="M50 14 Q60 20 62 30 Q76 18 82 30 Q86 40 74 46 Q90 52 84 66 Q78 76 66 70 Q68 86 54 86 Q44 88 42 76 Q30 90 20 80 Q12 70 24 62 Q8 56 12 44 Q18 32 30 38 Q28 22 38 18 Q44 12 50 14Z" {...f(c)} /><circle cx="88" cy="16" r="4" {...f(c)} /><circle cx="12" cy="86" r="5" {...f(c)} /><circle cx="86" cy="86" r="3" {...f(c)} /><Shine d="M34 32 Q38 26 46 26" /></g>;
const K = {
  red: ['สีแดง', splat('#ff4a4a')], orange: ['สีส้ม', splat('#ff9a3a')], yellow: ['สีเหลือง', splat('#ffd93a')], green: ['สีเขียว', splat('#4ac46a')],
  sky: ['สีฟ้า', splat('#6ac4ff')], blue: ['สีน้ำเงิน', splat('#4a6ae8')], purple: ['สีม่วง', splat('#9a6ae8')], pink: ['สีชมพู', splat('#ff8ac0')],
  white: ['สีขาว', splat('#ffffff')], black: ['สีดำ', splat('#3a3440')],
};

const CATS = [['animal', A], ['food', B], ['weapon', C], ['thing', D], ['nature', E], ['place', F], ['body', G], ['mood', H], ['color', K]];
export const EV = {};
CATS.forEach(([cat, set]) => Object.entries(set).forEach(([id, [n, art]]) => { EV[id] = { n, cat, art }; }));
export const EV_IDS = Object.keys(EV);

export function EvArt({ id }) {
  const e = EV[id]; if (!e) return null;
  return <svg viewBox="0 0 100 100" role="img" aria-label={e.n} className="ev-svg">
    <rect x="1" y="1" width="98" height="98" rx="16" fill={BG[e.cat]} />
    <circle cx="50" cy="50" r="40" fill="#fff" opacity=".35" />
    {e.art}
  </svg>;
}
